package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_appendFixedWidthPadLeft_TriageGen0Test {

    @Test
    public void testAppendFixedWidthPadLeft_NormalPadding() {
        StrBuilder sb = new StrBuilder();
        // obj="abc", width=5, padChar=' ' -> "  abc"
        sb.appendFixedWidthPadLeft("abc", 5, ' ');
        assertEquals("  abc", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_NoPaddingNeeded() {
        StrBuilder sb = new StrBuilder();
        // obj="abcdef", width=3, padChar=' ' -> "def" (logic: strLen >= width, strLen % width = 0, getChars(0, 6, buffer, 0))
        // Note: The provided implementation handles strLen >= width by taking strLen % width as start index.
        // If strLen=6, width=3, 6%3=0. It copies 6 chars into buffer.
        sb.appendFixedWidthPadLeft("abcdef", 3, ' ');
        assertEquals("abcdef", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_ExactWidth() {
        StrBuilder sb = new StrBuilder();
        // obj="abc", width=3, padChar=' ' -> "abc"
        sb.appendFixedWidthPadLeft("abc", 3, ' ');
        assertEquals("abc", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_NullObject() {
        StrBuilder sb = new StrBuilder();
        sb.setNullText("NULL");
        // obj=null, width=6, padChar='0' -> "00NULL"
        sb.appendFixedWidthPadLeft(null, 6, '0');
        assertEquals("00NULL", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthZeroOrLess() {
        StrBuilder sb = new StrBuilder("start");
        // width <= 0 should do nothing
        sb.appendFixedWidthPadLeft("test", 0, ' ');
        assertEquals("start", sb.toString());

        sb.appendFixedWidthPadLeft("test", -1, ' ');
        assertEquals("start", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_IntegerObject() {
        StrBuilder sb = new StrBuilder();
        // obj=123, width=5, padChar='0' -> "00123"
        sb.appendFixedWidthPadLeft(123, 5, '0');
        assertEquals("00123", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_LargeWidth() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadLeft("a", 10, 'x');
        assertEquals("xxxxxxxxxa", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_ModuloBehavior() {
        // Testing the specific branch: if (strLen >= width) { str.getChars(strLen % width, strLen, buffer, size); }
        // If str="12345", width=2. strLen=5. 5%2 = 1.
        // It copies from index 1 to 5 (chars '2345') to buffer.
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadLeft("12345", 2, ' ');
        assertEquals("2345", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_EmptyString() {
        StrBuilder sb = new StrBuilder();
        // obj="", width=3, padChar='*' -> "***"
        sb.appendFixedWidthPadLeft("", 3, '*');
        assertEquals("***", sb.toString());
    }
}
